function route(){let hashKey=location.hash.replace('#','').split('?')[0];let fileKey=location.pathname.split('/').pop().replace(/\.html?$/i,'');let key=(hashKey && pages[hashKey])?hashKey:(fileKey==='index'?'home':fileKey);if(!pages[key])key='home';const p=pages[key];document.title=p.title;document.querySelector('meta[name="description"]').setAttribute('content',p.desc);document.getElementById('app').innerHTML=p.render();document.getElementById('app').classList.remove('route-enter');void document.getElementById('app').offsetWidth;document.getElementById('app').classList.add('route-enter');document.querySelectorAll('.links a').forEach(a=>{const href=a.getAttribute('href');const target=href==='index.html'?'home':href.replace(/\.html?$/i,'');const active=target===key;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.getElementById('navLinks').classList.remove('open');document.getElementById('menuToggle').setAttribute('aria-expanded','false');document.getElementById('menuToggle').textContent='☰';observeReveals();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function observeReveals(){const els=document.querySelectorAll('.reveal');if(!('IntersectionObserver'in window)){els.forEach(e=>e.classList.add('show'));return;}const io=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('show');io.unobserve(entry.target)}}),{threshold:.12});els.forEach(e=>io.observe(e));}
document.getElementById('menuToggle').addEventListener('click',()=>{const n=document.getElementById('navLinks');const open=n.classList.toggle('open');document.getElementById('menuToggle').setAttribute('aria-expanded',String(open));document.getElementById('menuToggle').textContent=open?'×':'☰';document.getElementById('menuToggle').setAttribute('aria-label',open?'Close navigation':'Open navigation')});
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',4200)}
document.addEventListener('submit',e=>{if(e.target.id==='contactForm'){e.preventDefault();const d=new FormData(e.target);const subject=encodeURIComponent('Website enquiry – '+(d.get('service')||'General enquiry'));const body=encodeURIComponent('Name: '+d.get('name')+'\\nEmail: '+d.get('email')+'\\nOrganisation: '+d.get('organisation')+'\\nArea of interest: '+d.get('service')+'\\n\\nMessage:\\n'+d.get('message'));toast('Opening your email application. Add the official recipient address before launch.');window.location.href='mailto:?subject='+subject+'&body='+body;}});
document.getElementById('year').textContent=new Date().getFullYear();window.addEventListener('hashchange',route);route();
